#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void to_upper(char *s)
{
    for (; *s; s++) *s = (char)toupper((unsigned char)*s);
}

static void to_lower(char *s)
{
    for (; *s; s++) *s = (char)tolower((unsigned char)*s);
}

static void reverse(char *s)
{
    char *left = s;
    char *right = s + strlen(s);
    if (right == left) return;
    right--;
    while (left < right) {
        char temp = *left;
        *left++ = *right;
        *right-- = temp;
    }
}

static int count_words(const char *s)
{
    int words = 0;
    int inside = 0;
    for (; *s; s++) {
        if (isspace((unsigned char)*s)) inside = 0;
        else if (!inside) { inside = 1; words++; }
    }
    return words;
}

static void replace(char *s, char from, char to)
{
    for (; *s; s++) {
        if (*s == from) *s = to;
    }
}

static void caesar(char *s, int shift)
{
    for (; *s; s++) {
        if (*s >= 'a' && *s <= 'z') *s = (char)('a' + (*s - 'a' + shift) % 26);
        else if (*s >= 'A' && *s <= 'Z') *s = (char)('A' + (*s - 'A' + shift) % 26);
    }
}

static int is_palindrome(const char *s)
{
    const char *left = s;
    const char *right = s + strlen(s);
    while (left < right) {
        if (!isalnum((unsigned char)*left)) { left++; continue; }
        if (!isalnum((unsigned char)right[-1])) { right--; continue; }
        if (tolower((unsigned char)*left) != tolower((unsigned char)right[-1])) return 0;
        left++;
        right--;
    }
    return 1;
}

/* Splits off the first word: returns the rest after one space (or the empty end). */
static char *rest_after_word(char *s)
{
    while (*s && *s != ' ') s++;
    if (*s == ' ') {
        *s = '\0';
        return s + 1;
    }
    return s;
}

static void run(char *line)
{
    char original[512];
    snprintf(original, sizeof original, "%s", line);
    char *command = line;
    char *text = rest_after_word(line);

    if (strcmp(command, "upper") == 0) {
        to_upper(text);
        printf("%s\n", text);
    } else if (strcmp(command, "lower") == 0) {
        to_lower(text);
        printf("%s\n", text);
    } else if (strcmp(command, "reverse") == 0) {
        reverse(text);
        printf("%s\n", text);
    } else if (strcmp(command, "words") == 0) {
        int n = count_words(text);
        printf("%d word%s\n", n, n == 1 ? "" : "s");
    } else if (strcmp(command, "replace") == 0) {
        if (strlen(text) < 4 || text[1] != ' ' || text[3] != ' ') {
            printf("Could not read: %s\n", original);
            return;
        }
        char from = text[0];
        char to = text[2];
        replace(text + 4, from, to);
        printf("%s\n", text + 4);
    } else if (strcmp(command, "caesar") == 0) {
        char *end = NULL;
        long shift = strtol(text, &end, 10);
        if (end == text || *end != ' ' || shift < 0 || shift > 25) {
            printf("Could not read: %s\n", original);
            return;
        }
        caesar(end + 1, (int)shift);
        printf("%s\n", end + 1);
    } else if (strcmp(command, "palindrome") == 0) {
        printf("%s\n", is_palindrome(text) ? "yes" : "no");
    } else {
        printf("Unknown command: %s\n", command);
    }
}

int main(void)
{
    char line[512];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;
        run(line);
    }
    return 0;
}
